using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table: reversed nibble values (0x0→0x0, 0x1→0x8, …, 0xF→0xF)
    private static ReadOnlySpan<byte> NibbleLut =>
    [
        0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
        0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
    ];

    // Full 256-entry scalar lookup table
    private static readonly byte[] Lut = BuildLut();

    private static byte[] BuildLut()
    {
        var lut = new byte[256];
        ReadOnlySpan<byte> nib = NibbleLut;
        for (int i = 0; i < 256; i++)
            lut[i] = (byte)((nib[i & 0xF] << 4) | nib[i >> 4]);
        return lut;
    }

    public static void ReverseInPlace(Span<byte> data)
    {
        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int length = data.Length;
        int i = 0;

        if (Avx2.IsSupported)
        {
            // Duplicate the 16-byte nibble LUT across both 128-bit lanes
            Vector256<byte> lut = Vector256.Create(
                Vector128.Create(NibbleLut),
                Vector128.Create(NibbleLut));
            Vector256<byte> mask = Vector256.Create((byte)0x0F);

            int lastBlockStart = length - Vector256<byte>.Count;
            for (; i <= lastBlockStart; i += Vector256<byte>.Count)
            {
                ref byte src = ref Unsafe.Add(ref ptr, i);
                Vector256<byte> v = Vector256.LoadUnsafe(ref src);

                // Reverse via nibble shuffle: swap and reverse each nibble
                Vector256<byte> lo = Avx2.Shuffle(lut, v & mask);
                Vector256<byte> hi = Avx2.Shuffle(lut, Avx2.ShiftRightLogical(v.AsUInt16(), 4).AsByte() & mask);

                Vector256<byte> result = Avx2.Or(Avx2.ShiftLeftLogical(lo.AsUInt16(), 4).AsByte(), hi);
                result.StoreUnsafe(ref src);
            }
        }
        else if (Ssse3.IsSupported)
        {
            Vector128<byte> lut = Vector128.Create(NibbleLut);
            Vector128<byte> mask = Vector128.Create((byte)0x0F);

            int lastBlockStart = length - Vector128<byte>.Count;
            for (; i <= lastBlockStart; i += Vector128<byte>.Count)
            {
                ref byte src = ref Unsafe.Add(ref ptr, i);
                Vector128<byte> v = Vector128.LoadUnsafe(ref src);

                Vector128<byte> lo = Ssse3.Shuffle(lut, v & mask);
                Vector128<byte> hi = Ssse3.Shuffle(lut, Sse2.ShiftRightLogical(v.AsUInt16(), 4).AsByte() & mask);

                Vector128<byte> result = Sse2.Or(Sse2.ShiftLeftLogical(lo.AsUInt16(), 4).AsByte(), hi);
                result.StoreUnsafe(ref src);
            }
        }
        else if (AdvSimd.IsSupported)
        {
            // ARM NEON: vtbl1 equivalent via Vector128.ShuffleUnsafe
            Vector128<byte> lut = Vector128.Create(NibbleLut);
            Vector128<byte> mask = Vector128.Create((byte)0x0F);

            int lastBlockStart = length - Vector128<byte>.Count;
            for (; i <= lastBlockStart; i += Vector128<byte>.Count)
            {
                ref byte src = ref Unsafe.Add(ref ptr, i);
                Vector128<byte> v = Vector128.LoadUnsafe(ref src);

                Vector128<byte> lo = AdvSimd.VectorTableLookup(lut, v & mask);
                Vector128<byte> hi = AdvSimd.VectorTableLookup(lut, AdvSimd.ShiftRightLogical(v.AsUInt16(), 4).AsByte() & mask);

                Vector128<byte> result = AdvSimd.Or(AdvSimd.ShiftLeftLogical(lo.AsUInt16(), 4).AsByte(), hi);
                result.StoreUnsafe(ref src);
            }
        }

        // Scalar tail via precomputed LUT
        byte[] scalarLut = Lut;
        for (; i < length; i++)
            Unsafe.Add(ref ptr, i) = scalarLut[Unsafe.Add(ref ptr, i)];
    }
